const auth = { Authorization: `Bearer ${$env.TAIGA_TOKEN}` };
const projectName = $node['Webhook Trigger'].json.body.body.project ?? 'hr-portal';
const slug = projectName.toString().toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

const existing = await this.helpers.httpRequest({ method: 'GET', url: `${$env.TAIGA_URL}/api/v1/projects/by_slug?slug=${slug}`, headers: auth, json: true, ignoreHttpStatusErrors: true });
if (existing && existing.id) {
  return [{ json: { taiga_project_id: existing.id, taiga_project_slug: existing.slug, taiga_project_created: false } }];
}

const created = await this.helpers.httpRequest({
  method: 'POST',
  url: `${$env.TAIGA_URL}/api/v1/projects`,
  headers: auth,
  json: true,
  body: { name: projectName, slug, description: `${projectName} \u2014 created by /kickoff`, creation_template: 1, is_backlog_activated: true, is_epics_activated: true, is_wiki_activated: true, is_issues_activated: true, is_kanban_activated: false }
});
return [{ json: { taiga_project_id: created.id, taiga_project_slug: created.slug, taiga_project_created: true } }];

// ponytail: one dedicated Taiga user per SDLC role (created once by
// helm/ansible/playbooks/role-accounts.yml) so tickets can be assigned to
// the role that did the work instead of the single shared admin identity.
// GitLab grants this at the `sdlc` GROUP level (cascades to every project
// automatically) -- Taiga has no group-membership concept, so each new
// project needs its own membership call here at kickoff time.
const auth = { Authorization: `Bearer ${$env.TAIGA_TOKEN}` };
const projectId = $json.taiga_project_id;
const sdlcRoles = ['backend-developer','data-engineer','devops-engineer','frontend-developer','product-owner','project-manager','qa-engineer','release-manager','security-engineer','solution-architect','tech-lead','uiux-designer'];

const allUsers = await this.helpers.httpRequest({ method: 'GET', url: `${$env.TAIGA_URL}/api/v1/users`, headers: auth, json: true });
const roles = await this.helpers.httpRequest({ method: 'GET', url: `${$env.TAIGA_URL}/api/v1/roles?project=${projectId}`, headers: auth, json: true });
// ponytail: membership `role` only affects permissions/points template, not
// what assigned_to can be set to -- every role-account gets the project's
// first role rather than building a role-name mapping that isn't needed.
const defaultRoleId = roles[0]?.id;

const added = [];
const skipped = [];
for (const roleName of sdlcRoles) {
  const user = allUsers.find(u => u.username === roleName);
  if (!user) { skipped.push(roleName); continue; }
  try {
    await this.helpers.httpRequest({ method: 'POST', url: `${$env.TAIGA_URL}/api/v1/memberships`, headers: auth, json: true, body: { project: projectId, user: user.id, role: defaultRoleId } });
    added.push(roleName);
  } catch (e) {
    // already a member -- Taiga 400s on duplicate membership, treat as success
    added.push(roleName);
  }
}
if (skipped.length) {
  console.log(`Role accounts not found in Taiga (run role-accounts.yml first): ${skipped.join(', ')}`);
}
return [{ json: { ...$json, role_members_added: added, role_members_skipped: skipped } }];
